# Model: for each marker, ray toward the FARTHER separator (perpendicular dist), recoloring path + sep cell;
# bands: sep_line +/- 1 rows/cols x marker +/- 1 cells -> sep color. Verify on demo 2.
def solve(g):
    H,W=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    sr=[r for r in range(H) if len({g[r][c] for c in range(W)})==1 and g[r][0]!=bg]
    sc=[c for c in range(W) if len({g[r][c] for r in range(H)})==1 and g[0][c]!=bg]
    sep=g[sr[0]][0] if sr else g[0][sc[0]]
    o=[row[:] for row in g]
    markers=[(r,c,g[r][c]) for r in range(H) for c in range(W)
             if g[r][c]!=bg and g[r][c]!=sep and r not in sr and c not in sc]
    # separators: split into groups by orientation; for horizontal seps, distance = |r-s| ; vertical: |c-s|
    hs=sr if sr else []
    vs=sc if sc else []
    def paint(r,c,col):
        if 0<=r<H and 0<=c<W and o[r][c]==bg: o[r][c]=col
    for mr,mc,mcol in markers:
